import { build } from "esbuild";
import { copyFile, mkdir, readFile, writeFile } from "node:fs/promises";

const output = new URL("../src/pytred/static/", import.meta.url);
const notices = [
  "The pytred source and wheel distributions bundle the following JavaScript\n" +
  "libraries in dataflow.js. File paths below are relative to this directory.\n" +
  "Generated by frontend/build.mjs; do not edit manually.\n",
];
const licenseTexts = [];
for (const name of ["cytoscape", "@dagrejs/dagre", "@dagrejs/graphlib", "highlight.js"]) {
  const location = new URL(`node_modules/${name}/`, import.meta.url);
  licenseTexts.push(await readFile(new URL("LICENSE", location), "utf8"));
  const pkg = JSON.parse(await readFile(new URL("package.json", location), "utf8"));
  const licenseDirectory = new URL(`licenses/${name}/`, output);
  await mkdir(licenseDirectory, { recursive: true });
  await copyFile(new URL("LICENSE", location), new URL("LICENSE", licenseDirectory));
  notices.push(
    `Name: ${name}\nVersion: ${pkg.version}\nFiles: dataflow.js\n` +
    `License: ${pkg.license}\nFor license text, see licenses/${name}/LICENSE\n`,
  );
}
await writeFile(new URL("LICENSES_bundled.txt", output), notices.join("\n"));

const result = await build({
  absWorkingDir: new URL(".", import.meta.url).pathname,
  entryPoints: ["dataflow.js"],
  outfile: new URL("dataflow.js", output).pathname,
  bundle: true,
  format: "iife",
  platform: "browser",
  target: "es2020",
  minify: true,
  legalComments: "inline",
  metafile: true,
  // HTML snapshots embed this bundle, so carry the full notices with the code.
  banner: { js: `/*!\n${licenseTexts.join("\n")}\n*/` },
});
for (const file of Object.values(result.metafile.outputs)) {
  if (file.imports.length) throw new Error("Graph bundle must not import external assets");
}
await copyFile(new URL("dataflow.css", import.meta.url), new URL("dataflow.css", output));
